import React, { useState } from "react";
import { useFormik } from "formik";
import * as Yup from 'yup'

const input = {
    name: '',
    email: '',
    no: '',
    add: '',
    city: '',
    gender: ''

}

const validate = Yup.object({
    name: Yup.string().min(2).max(10).required("plz enter your first first name"),
    email: Yup.string().email().required('Plz enter your email')
})

function Form() {
    const [getdata, setgetdata] = useState(input)

    const { values, errors, touched, handleBlur, handleChange, handleSubmit } = useFormik({
        initialValues: input,
        validationSchema: validate,
        onSubmit: async (values) => {
            try {
                const res = await fetch('http://localhost:7000/user/register', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(values)

                });
                const data = await res.json();
                console.log(data);
                if (res.ok) {
                    alert('registered successfully');
                }
                else {
                    alert('registration failed');
                }
            }
            catch (err) {
                console.log(err);
                alert("server error");
            }
        }
        })
    
    return (
        <div>
            <h1>Student Form</h1>
            <form action="" onSubmit={handleSubmit}>
                <div>
                    <label htmlFor="">student name</label>
                    <input type="text" name="name" value={values.name} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.name && touched.name) && <font color='red'>{errors.name}</font>}
                </div>
                <div>
                    <label htmlFor="">email</label>
                    <input type="text" name="email" value={values.email} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.email && touched.email) && <font color='red'>{errors.email}</font>}
                </div>
                <div>
                    <label htmlFor="">no</label>
                    <input type="text" name="no" value={values.no} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.no && touched.no) && <font color='red'>{errors.no}</font>}
                </div>

                <div>
                    <label htmlFor="">address</label>
                    <input type="text" name="add" value={values.add} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.add && touched.add) && <font color='red'>{errors.add}</font>}
                </div>
                <div className="col-md-4">
                    <label htmlFor="inputState" className="form-label">City</label>
                    <select id="inputState" className="form-select" name='city' value={values.city} onChange={handleChange} onBlur={handleBlur} >
                        <option value=''>Select City</option>
                        <option value='Surat'>Surat</option>
                        <option value='Vapi'>Vapi</option>
                        <option value='Valsad'>Valsad</option>
                        <option value='Navsari'>Navsari</option>
                        <option value='Baroda'>Baroda</option>
                    </select>

                </div>
                <div>
                    <label htmlFor="">Gender</label>
                    <div>
                        <div>
                            <input type="radio" name="gender" value='male' onChange={handleChange} onBlur={handleBlur} />
                            <label htmlFor="">Male</label>
                        </div>
                    </div>
                    <div>
                        <div>
                            <input type="radio" name="gender" value='Female' onChange={handleChange} onBlur={handleBlur} />
                            <label htmlFor="">female</label>
                        </div>
                    </div>
                </div>
                <div>
                    <button type="submit">submit</button>
                </div>
            </form>
            <table>
                <thead>
                    <tr>
                        <th>name</th>
                        <th>email</th>
                        <th>no</th>
                        <th>address</th>
                        <th>city</th>
                        <th>gender</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>{getdata.name}</td>
                        <td>{getdata.email}</td>
                        <td>{getdata.no}</td>
                        <td>{getdata.add}</td>
                        <td>{getdata.city}</td>
                        <td>{getdata.gender}</td>
                    </tr>
                </tbody>
            </table>
        </div>
    )

}
export default Form
